ALTER TABLE users ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', ADD COLUMN updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE activities ADD COLUMN signup_start DATETIME NULL, ADD COLUMN signup_end DATETIME NULL, ADD COLUMN place_name VARCHAR(160), ADD COLUMN address VARCHAR(500), ADD COLUMN updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE products ADD COLUMN redeemed_stock INT NOT NULL DEFAULT 0, ADD COLUMN created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, ADD COLUMN updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;
ALTER TABLE point_logs ADD COLUMN biz_type VARCHAR(40), ADD COLUMN biz_id VARCHAR(80), ADD COLUMN idempotency_key VARCHAR(160), ADD COLUMN operator_admin_id BIGINT, ADD COLUMN expires_at DATETIME, ADD UNIQUE KEY uk_point_idempotency(idempotency_key), ADD INDEX idx_point_user_time(user_id,created_at);
ALTER TABLE orders ADD COLUMN idempotency_key VARCHAR(80), ADD COLUMN product_name VARCHAR(200), ADD COLUMN product_cover_url VARCHAR(500), ADD COLUMN phone_snapshot VARCHAR(30), ADD COLUMN picked_at DATETIME, ADD COLUMN canceled_at DATETIME, ADD COLUMN cancel_reason VARCHAR(300), ADD COLUMN operator_admin_id BIGINT, ADD UNIQUE KEY uk_order_user_request(user_id,idempotency_key), ADD INDEX idx_order_expire(status,expire_at);
ALTER TABLE admins ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', ADD COLUMN last_login_at DATETIME;
ALTER TABLE daily_checkins MODIFY points INT NOT NULL DEFAULT 10;
CREATE TABLE point_lots (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, source_log_id BIGINT NOT NULL, original_amount INT NOT NULL, available_amount INT NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_lot_spend(user_id,expires_at,available_amount));
CREATE TABLE point_lot_usages (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, lot_id BIGINT NOT NULL, amount INT NOT NULL, refunded_amount INT NOT NULL DEFAULT 0, UNIQUE KEY uk_order_lot(order_id,lot_id));
CREATE TABLE activity_participations (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, activity_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'REGISTERED', registered_at DATETIME NOT NULL, checked_in_at DATETIME, checkin_method VARCHAR(30), UNIQUE KEY uk_user_activity(user_id,activity_id), INDEX idx_participation_activity(activity_id,status));
CREATE TABLE questionnaires (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(200) NOT NULL, description TEXT, start_time DATETIME NOT NULL, end_time DATETIME NOT NULL, reward_points INT NOT NULL DEFAULT 100, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', pinned BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE questionnaire_questions (id BIGINT PRIMARY KEY AUTO_INCREMENT, questionnaire_id BIGINT NOT NULL, question_type VARCHAR(20) NOT NULL, title VARCHAR(500) NOT NULL, options_json TEXT, required BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0, INDEX idx_questionnaire_sort(questionnaire_id,sort_order));
CREATE TABLE questionnaire_responses (id BIGINT PRIMARY KEY AUTO_INCREMENT, questionnaire_id BIGINT NOT NULL, user_id BIGINT NOT NULL, response_month CHAR(7) NOT NULL, answers_json LONGTEXT NOT NULL, reward_points INT NOT NULL DEFAULT 100, submitted_at DATETIME NOT NULL, UNIQUE KEY uk_response_user_month(user_id,response_month), INDEX idx_response_questionnaire(questionnaire_id));
CREATE TABLE content_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, content_type VARCHAR(40) NOT NULL, title VARCHAR(200), image_url VARCHAR(500), content LONGTEXT, sort_order INT NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT TRUE, activity_id BIGINT, latitude DECIMAL(10,7), longitude DECIMAL(10,7), address VARCHAR(500), updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_content_type(content_type,enabled,sort_order));
CREATE TABLE file_assets (id BIGINT PRIMARY KEY AUTO_INCREMENT, original_name VARCHAR(255) NOT NULL, storage_key VARCHAR(500) NOT NULL, public_url VARCHAR(500) NOT NULL, content_type VARCHAR(100), size_bytes BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
